<?php
 class CustomView extends \Slim\View { public function render($template, $data = null) { echo "Custom view"; } } class EchoErrorLogger { public function error($object) { echo get_class($object) .':'.$object->getMessage(); } } class Derived extends \Slim\Slim { public static function getDefaultSettings() { return array_merge( array("late-static-binding" => true) , parent::getDefaultSettings()); } } class CustomMiddleware extends \Slim\Middleware { public function call() { $env = $this->app->environment(); $res = $this->app->response(); $env['slim.test'] = 'Hello'; $this->next->call(); $res->header('X-Slim-Test', 'Hello'); $res->write('Hello'); } } class SlimTest extends PHPUnit_Framework_TestCase { public function setUp() { unset($_ENV['SLIM_MODE']); $_SESSION = array(); \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'QUERY_STRING' => 'one=foo&two=bar', 'SERVER_NAME' => 'slimframework.com', )); } public function testHasVersionConstant() { $this->assertTrue(is_string(\Slim\Slim::VERSION)); } public function testDefaultInstanceProperties() { $s = new \Slim\Slim(); $this->assertInstanceOf('\Slim\Http\Request', $s->request()); $this->assertInstanceOf('\Slim\Http\Response', $s->response()); $this->assertInstanceOf('\Slim\Router', $s->router()); $this->assertInstanceOf('\Slim\View', $s->view()); $this->assertInstanceOf('\Slim\Log', $s->getLog()); $this->assertEquals(\Slim\Log::DEBUG, $s->getLog()->getLevel()); $this->assertTrue($s->getLog()->getEnabled()); $this->assertInstanceOf('\Slim\Environment', $s->environment()); } public function testGetDefaultInstance() { $s = new \Slim\Slim(); $s->setName('default'); $this->assertEquals('default', $s->getName()); $this->assertInstanceOf('\Slim\Slim', \Slim\Slim::getInstance()); $this->assertSame($s, \Slim\Slim::getInstance()); } public function testGetNamedInstance() { $s = new \Slim\Slim(); $s->setName('foo'); $this->assertSame($s, \Slim\Slim::getInstance('foo')); } public function testSlimAutoloaderIgnoresNonSlimClass() { $foo = new Foo(); } public function testGetSettingThatExists() { $s = new \Slim\Slim(); $this->assertEquals('./templates', $s->config('templates.path')); } public function testGetSettingThatDoesNotExist() { $s = new \Slim\Slim(); $this->assertNull($s->config('foo')); } public function testSetSetting() { $s = new \Slim\Slim(); $this->assertEquals('./templates', $s->config('templates.path')); $s->config('templates.path', './tmpl'); $this->assertEquals('./tmpl', $s->config('templates.path')); } public function testBatchSetSettings() { $s = new \Slim\Slim(); $this->assertEquals('./templates', $s->config('templates.path')); $this->assertTrue($s->config('debug')); $s->config(array( 'templates.path' => './tmpl', 'debug' => false )); $this->assertEquals('./tmpl', $s->config('templates.path')); $this->assertFalse($s->config('debug')); } public function testSetSettingsRecursively() { $config = array( 'my_module' => array( 'paths' => array( './my_module/path/1', ), ) ); $s = new \Slim\Slim($config); $override = array( 'my_module' => array( 'paths' => array( './my_module/path/2', './my_module/path/3', ), ) ); $s->config($override, true); $expected = array( 'paths' => array( './my_module/path/1', './my_module/path/2', './my_module/path/3', ), ); $this->assertEquals($expected, $s->config('my_module')); $s = new \Slim\Slim($config); $s->config($override); $this->assertNotEquals($expected, $s->config('my_module')); } public function testGetDefaultMode() { $s = new \Slim\Slim(); $this->assertEquals('development', $s->getMode()); } public function testGetModeFromEnvironment() { $_ENV['SLIM_MODE'] = 'production'; $s = new \Slim\Slim(); $this->assertEquals('production', $s->getMode()); } public function testGetModeFromSettings() { $s = new \Slim\Slim(array( 'mode' => 'test' )); $this->assertEquals('test', $s->getMode()); } public function testModeConfiguration() { $flag = 0; $configureTest = function () use (&$flag) { $flag = 'test'; }; $configureProduction = function () use (&$flag) { $flag = 'production'; }; $s = new \Slim\Slim(array('mode' => 'test')); $s->configureMode('test', $configureTest); $s->configureMode('production', $configureProduction); $this->assertEquals('test', $flag); } public function testModeConfigurationWhenModeDoesNotMatch() { $flag = 0; $configureTest = function () use (&$flag) { $flag = 'test'; }; $s = new \Slim\Slim(array('mode' => 'production')); $s->configureMode('test', $configureTest); $this->assertEquals(0, $flag); } public function testModeConfigurationWhenNotCallable() { $flag = 0; $s = new \Slim\Slim(array('mode' => 'production')); $s->configureMode('production', 'foo'); $this->assertEquals(0, $flag); } public function testGetModeFromGetEnv() { putenv('SLIM_MODE=production'); $s = new \Slim\Slim(); $this->assertEquals('production', $s->getMode()); } public function testGenericRoute() { $s = new \Slim\Slim(); $callable = function () { echo "foo"; }; $route = $s->map('/bar', $callable); $this->assertInstanceOf('\Slim\Route', $route); $this->assertEmpty($route->getHttpMethods()); } public function testGetRouteIsAlsoMappedAsHead() { $s = new \Slim\Slim(); $route = $s->get('/foo', function () {}); $this->assertTrue($route->supportsHttpMethod(\Slim\Http\Request::METHOD_GET)); $this->assertTrue($route->supportsHttpMethod(\Slim\Http\Request::METHOD_HEAD)); } public function testGetRoute() { $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->get('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testPostRoute() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->post('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testPutRoute() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->put('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testPatchRoute() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PATCH', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->patch('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testDeleteRoute() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'DELETE', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->delete('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testOptionsRoute() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'OPTIONS', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $route = $s->options('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } public function testRouteGroups() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'GET', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar/baz', )); $s = new \Slim\Slim(); $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $s->group('/bar', $mw1, function () use ($s, $mw2, $callable) { $s->get('/baz', $mw2, $callable); }); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); } public function testAnyRoute() { $mw1 = function () { echo "foo"; }; $mw2 = function () { echo "bar"; }; $callable = function () { echo "xyz"; }; $methods = array('GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'); foreach ($methods as $i => $method) { \Slim\Environment::mock(array( 'REQUEST_METHOD' => $method, 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $route = $s->any('/bar', $mw1, $mw2, $callable); $s->call(); $this->assertEquals('foobarxyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); $this->assertSame($callable, $route->getCallable()); } } public function testRouteWithoutSlashAndUrlWithOne() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar/', )); $s = new \Slim\Slim(); $s->get('/bar', function () { echo "xyz"; }); $s->call(); $this->assertEquals(404, $s->response()->status()); } public function testRouteMatchesInCaseInsensitiveMannerIfConfigured() { \Slim\Environment::mock(array( 'PATH_INFO' => '/BaR', )); $s = new \Slim\Slim(array('routes.case_sensitive' => false)); $route = $s->get('/bar', function () { echo "xyz"; }); $s->call(); $this->assertEquals(200, $s->response()->status()); $this->assertEquals('xyz', $s->response()->body()); $this->assertEquals('/bar', $route->getPattern()); } public function testRouteWithUrlEncodedCharacters() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar/jo%20hn/smi%20th', )); $s = new \Slim\Slim(); $s->get('/bar/:one/:two', function ($one, $two) { echo $one . $two; }); $s->call(); $this->assertEquals('jo hnsmi th', $s->response()->body()); } public function testSetSlimViewFromString() { $s = new \Slim\Slim(); $this->assertInstanceOf('\Slim\View', $s->view()); $s->view('CustomView'); $this->assertInstanceOf('CustomView', $s->view()); } public function testSetSlimViewFromInstance() { $s = new \Slim\Slim(); $this->assertInstanceOf('\Slim\View', $s->view()); $s->view(new CustomView()); $this->assertInstanceOf('CustomView', $s->view()); } public function testViewDataTransfer() { $data = array('foo' => 'bar'); $s = new \Slim\Slim(); $s->view()->setData($data); $s->view('CustomView'); $this->assertSame($data, $s->view()->getData()); } public function testViewGetsTemplatesPath() { $path = dirname(__FILE__) . '/templates'; $s = new \Slim\Slim(array('templates.path' => $path)); $this->assertEquals($s->view->getTemplatesDirectory(), $path); } public function testRenderTemplateWithData() { $s = new \Slim\Slim(array('templates.path' => dirname(__FILE__) . '/templates')); $s->get('/bar', function () use ($s) { $s->render('test.php', array('foo' => 'bar')); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(200, $status); $this->assertEquals('test output bar', $body); } public function testRenderTemplateWithDataAndStatus() { $s = new \Slim\Slim(array('templates.path' => dirname(__FILE__) . '/templates')); $s->get('/bar', function () use ($s) { $s->render('test.php', array('foo' => 'bar'), 500); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(500, $status); $this->assertEquals('test output bar', $body); } public function testGetLog() { $s = new \Slim\Slim(); $this->assertInstanceOf('\Slim\Log', $s->getLog()); } public function testLastModifiedMatch() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'GET', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'HTTP_IF_MODIFIED_SINCE' => 'Sun, 03 Oct 2010 21:00:52 GMT', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->lastModified(1286139652); }); $s->call(); $this->assertEquals(304, $s->response()->status()); } public function testLastModifiedDoesNotMatch() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'IF_MODIFIED_SINCE' => 'Sun, 03 Oct 2010 21:00:52 GMT', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->lastModified(1286139250); }); $s->call(); $this->assertEquals(200, $s->response()->status()); } public function testLastModifiedOnlyAcceptsIntegers() { $this->setExpectedException('\InvalidArgumentException'); \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->lastModified('Test'); }); $s->call(); } public function testLastModifiedHeaderFormat() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->lastModified(1286139652); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertTrue(isset($header['Last-Modified'])); $this->assertEquals('Sun, 03 Oct 2010 21:00:52 GMT', $header['Last-Modified']); } public function testEtagMatches() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'HTTP_IF_NONE_MATCH' => '"abc123"', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->etag('abc123'); }); $s->call(); $this->assertEquals(304, $s->response()->status()); } public function testEtagDoesNotMatch() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'IF_NONE_MATCH' => '"abc1234"', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->etag('abc123'); }); $s->call(); $this->assertEquals(200, $s->response()->status()); } public function testETagWithInvalidType() { $this->setExpectedException('\InvalidArgumentException'); \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'IF_NONE_MATCH' => '"abc1234"', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->etag('123','foo'); }); $s->call(); } public function testExpiresAsString() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->expires('5 days'); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertTrue(isset($header['Expires'])); $this->assertEquals( safe_strtotime('5 days'), safe_strtotime($header['Expires']), 1 ); } public function testExpiresAsInteger() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $fiveDaysFromNow = time() + (60 * 60 * 24 * 5); $expectedDate = gmdate('D, d M Y H:i:s T', $fiveDaysFromNow); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s, $fiveDaysFromNow) { $s->expires($fiveDaysFromNow); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertTrue(isset($header['Expires'])); $this->assertEquals($header['Expires'], $expectedDate); } public function testSetCookie() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->setCookie('foo', 'bar', '2 days'); $s->setCookie('foo1', 'bar1', '2 days'); }); $s->call(); $cookie1 = $s->response->cookies->get('foo'); $cookie2 = $s->response->cookies->get('foo1'); $this->assertEquals(2, count($s->response->cookies)); $this->assertEquals('bar', $cookie1['value']); $this->assertEquals('bar1', $cookie2['value']); } public function testGetCookie() { \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'GET', 'REMOTE_ADDR' => '127.0.0.1', 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'QUERY_STRING' => 'one=foo&two=bar', 'SERVER_NAME' => 'slimframework.com', 'SERVER_PORT' => 80, 'HTTP_COOKIE' => 'foo=bar; foo2=bar2', 'slim.url_scheme' => 'http', 'slim.input' => '', 'slim.errors' => @fopen('php://stderr', 'w') )); $s = new \Slim\Slim(); $this->assertEquals('bar', $s->getCookie('foo')); $this->assertEquals('bar2', $s->getCookie('foo2')); } public function testGetCookieThatDoesNotExist() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', )); $s = new \Slim\Slim(); $this->assertNull($s->getCookie('foo')); } public function testDeleteCookie() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar', 'COOKIE' => 'foo=bar; foo2=bar2', )); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->setCookie('foo', 'bar'); $s->deleteCookie('foo'); }); $s->call(); $cookie = $s->response->cookies->get('foo'); $this->assertEquals(1, count($s->response->cookies)); $this->assertEquals('', $cookie['value']); $this->assertLessThan(time(), $cookie['expires']); } public function testGetRoot() { $_SERVER['DOCUMENT_ROOT'] = dirname(__FILE__); $s = new \Slim\Slim(); $this->assertEquals($_SERVER['DOCUMENT_ROOT'] . '/foo/', $s->root()); } public function testStop() { $this->setExpectedException('\Slim\Exception\Stop'); $s = new \Slim\Slim(); $s->stop(); } public function testStopWithSubsequentOutput() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo"; $s->stop(); echo "Bar"; }); $s->call(); $this->assertEquals('Foo', $s->response()->body()); } public function testStopOutputWithOutputBufferingOnAndPreContent() { $this->expectOutputString('1.2.Foo.3'); echo "1."; $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo"; $s->stop(); }); echo "2."; $s->run(); echo ".3"; } public function testStopDoesNotLeaveOutputBuffersOpen() { $level_start = ob_get_level(); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->stop(); }); $s->run(); $this->assertEquals($level_start, ob_get_level()); } public function testHalt() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo!"; $s->halt(500, 'Something broke'); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(500, $status); $this->assertEquals('Something broke', $body); } public function testHaltOutputWithOutputBufferingOnAndPreContent() { $this->expectOutputString('1.2.Something broke.3'); echo "1."; $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo!"; $s->halt(500, 'Something broke'); }); echo "2."; $s->run(); echo ".3"; } public function testHaltDoesNotLeaveOutputBuffersOpen() { $level_start = ob_get_level(); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->halt(500, ''); }); $s->run(); $this->assertEquals($level_start, ob_get_level()); } public function testPass() { ob_start(); $s = new \Slim\Slim(); echo "Foo"; try { $s->pass(); $this->fail('Did not catch Slim_Exception_Pass'); } catch ( \Slim\Exception\Pass $e ) {} $output = ob_get_clean(); $this->assertEquals('', $output); } public function testPassWithSubsequentRoute() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/name/Frank', )); $s = new \Slim\Slim(); $s->get('/name/Frank', function () use ($s) { echo "Fail"; $s->pass(); }); $s->get('/name/:name', function ($name) { echo $name; }); $s->call(); $this->assertEquals('Frank', $s->response()->body()); } public function testPassWithoutSubsequentRoute() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/name/Frank', )); $s = new \Slim\Slim(); $s->get('/name/Frank', function () use ($s) { echo "Fail"; $s->pass(); }); $s->call(); $this->assertEquals(404, $s->response()->status()); } public function testContentType() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->contentType('application/json'); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals('application/json', $header['Content-Type']); } public function testStatus() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->status(403); }); $s->call(); $this->assertEquals(403, $s->response()->status()); } public function testSlimUrlFor() { $s = new \Slim\Slim(); $s->get('/hello/:name', function () {})->name('hello'); $this->assertEquals('/foo/hello/Josh', $s->urlFor('hello', array('name' => 'Josh'))); } public function testRedirect() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo"; $s->redirect('/somewhere/else', 303); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(303, $status); $this->assertEquals('/somewhere/else', $header['Location']); $this->assertEquals('', $body); } public function testRun() { $this->expectOutputString('Foo'); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { echo "Foo"; }); $s->run(); } public function testRunOutputWithOutputBufferingOnAndPreContent() { $this->expectOutputString('1.2.Foo.3'); $s = new \Slim\Slim(); echo "1."; $s->get('/bar', function () use ($s) { echo "Foo"; }); echo "2."; $s->run(); echo ".3"; } public function testRunDoesNotLeaveAnyOutputBuffersOpen() { $level_start = ob_get_level(); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) {}); $s->run(); $this->assertEquals($level_start, ob_get_level()); } public function testAddMiddleware() { $this->expectOutputString('FooHello'); $s = new \Slim\Slim(); $s->add(new CustomMiddleware()); $s->get('/bar', function () { echo 'Foo'; }); $s->run(); $this->assertEquals('Hello', $s->response()->header('X-Slim-Test')); } public function testFailureWhenAddingCircularMiddleware() { $this->setExpectedException('\RuntimeException'); $middleware = new CustomMiddleware; $s = new \Slim\Slim; $s->add($middleware); $s->add(new CustomMiddleware); $s->add($middleware); $s->run(); } public function testSetFlashForNextRequest() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->flash('info', 'bar'); }); $this->assertFalse(isset($_SESSION['slim.flash'])); $s->run(); $this->assertEquals('bar', $_SESSION['slim.flash']['info']); } public function testSetFlashForCurrentRequest() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->flashNow('info', 'bar'); }); $s->run(); $env = $s->environment(); $this->assertEquals('bar', $env['slim.flash']['info']); } public function testKeepFlashForNextRequest() { $_SESSION['slim.flash'] = array('info' => 'Foo'); $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->flashKeep(); }); $s->run(); $this->assertEquals('Foo', $_SESSION['slim.flash']['info']); } public function testFlashData() { $s = new \Slim\Slim(); $s->get('/bar', function () use ($s) { $s->flashNow('info', 'bar'); }); $s->run(); $this->assertEquals(array('info' => 'bar'), $s->flashData()); } public function testNotFound() { $s = new \Slim\Slim(); $s->notFound(function () { echo "Not Found"; }); $s->get('/foo', function () {}); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(404, $status); $this->assertEquals('Not Found', $body); } public function testSlimError() { $s = new \Slim\Slim(array( "log.enabled" => false )); $s->get('/bar', function () use ($s) { $s->error(); }); $s->call(); $this->assertEquals(500, $s->response()->status()); } public function testDefaultHandlerLogsTheErrorWhenDebugIsFalse() { $s = new \Slim\Slim(array('debug' => false)); $s->container->singleton('log', function ($c) { return new EchoErrorLogger(); }); $s->get('/bar', function () use ($s) { throw new \InvalidArgumentException('my specific error message'); }); ob_start(); $s->run(); $output = ob_get_clean(); $this->assertTrue(safe_strpos($output, 'InvalidArgumentException:my specific error message') !== false); } public function DISABLEDtestTriggeredErrorsAreConvertedToErrorExceptions() { $s = new \Slim\Slim(array( 'debug' => false )); $s->error(function ( $e ) { if ($e instanceof \ErrorException) { echo $e->getMessage(); } }); $s->get('/bar', function () { trigger_error('Foo I say!'); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(500, $status); $this->assertEquals('Foo I say!', $body); } public function testErrorWithMultipleApps() { $s1 = new \Slim\Slim(array( 'debug' => false, 'log.enabled' => false )); $s2 = new \Slim\Slim(); $s1->get('/bar', function () use ($s1) { $s1->error(); }); $s2->get('/bar', function () { echo 'success'; }); $s1->call(); $s2->call(); $this->assertEquals(500, $s1->response()->status()); $this->assertEquals(200, $s2->response()->status()); } public function testErrorHandlerUsesCurrentResponseObject() { $s = new \Slim\Slim(array( 'debug' => false )); $s->error(function ( \Exception $e ) use ($s) { $r = $s->response(); $r->status(503); $r->write('Foo'); $r['X-Powered-By'] = 'Slim'; echo 'Bar'; }); $s->get('/bar', function () { throw new \Exception('Foo'); }); $s->call(); list($status, $header, $body) = $s->response()->finalize(); $this->assertEquals(503, $status); $this->assertEquals('FooBar', $body); $this->assertEquals('Slim', $header['X-Powered-By']); } public function testHandleErrors() { $defaultErrorReporting = error_reporting(); error_reporting(E_ALL ^ E_NOTICE); try { \Slim\Slim::handleErrors(E_NOTICE, 'test error', 'Slim.php', 119); } catch (\ErrorException $e) { $this->fail('Slim::handleErrors reported a disabled error level.'); } error_reporting(E_ALL | E_STRICT); try { \Slim\Slim::handleErrors(E_STRICT, 'test error', 'Slim.php', 119); $this->fail('Slim::handleErrors didn\'t report a enabled error level'); } catch (\ErrorException $e) {} error_reporting($defaultErrorReporting); } public function testErrorHandler() { $s = new \Slim\Slim(); $errCallback = function () { echo "404"; }; $s->error($errCallback); $this->assertSame($errCallback, PHPUnit_Framework_Assert::readAttribute($s, 'error')); } public function testErrorHandlerIfNotCallable() { $this->setExpectedException('\Slim\Exception\Stop'); $s = new \Slim\Slim(array("log.enabled" => false)); $errCallback = 'foo'; $s->error($errCallback); } public function testNotFoundHandler() { $s = new \Slim\Slim(); $notFoundCallback = function () { echo "404"; }; $s->notFound($notFoundCallback); $this->assertSame($notFoundCallback, PHPUnit_Framework_Assert::readAttribute($s, 'notFound')); } public function testNotFoundHandlerIfNotCallable() { $this->setExpectedException('\Slim\Exception\Stop'); $s = new \Slim\Slim(); $notFoundCallback = 'foo'; $s->notFound($notFoundCallback); } public function testRegistersAndCallsHooksByPriority() { $this->expectOutputString('barfoo'); $app = new \Slim\Slim(); $callable1 = function () { echo "foo"; }; $callable2 = function () { echo "bar"; }; $app->hook('test.hook.one', $callable1); $app->hook('test.hook.one', $callable2, 8); $hooks = $app->getHooks(); $this->assertEquals(7, count($hooks)); $app->applyHook('test.hook.one'); } public function testHookInvalidCallable() { $app = new \Slim\Slim(); $callable = 'test'; $app->hook('test.hook.one', $callable); $this->assertEquals(array(array()), $app->getHooks('test.hook.one')); } public function testHookInvocationIfNotExists() { $app = new \Slim\Slim(); $app->applyHook('test.hook.one'); $this->assertEquals(array(array()), $app->getHooks('test.hook.one')); } public function testHookClear() { $app = new \Slim\Slim(); $app->hook('test.hook.one', function () {}); $app->hook('test.hook.two', function () {}); $app->clearHooks('test.hook.two'); $this->assertEquals(array(array()), $app->getHooks('test.hook.two')); $hookOne = $app->getHooks('test.hook.one'); $this->assertTrue(count($hookOne[10]) === 1); $app->clearHooks(); $this->assertEquals(array(array()), $app->getHooks('test.hook.one')); } public function testHooksMultipleArguments() { $testArgA = 'argumentA'; $testArgB = 'argumentB'; $this->expectOutputString($testArgA . $testArgB); $app = new \Slim\Slim(); $app->hook('test.hook.one', function ($argA, $argB) { echo $argA . $argB; }); $app->applyHook('test.hook.one', $testArgA, $testArgB); } public function testDerivedClassCanOverrideStaticFunction() { $app = new Derived(); $this->assertEquals($app->config("late-static-binding"), true); } } 